+@page "/shipments/{TrackingNumber}"
+@rendermode InteractiveAuto
+@using sv_c95fa2b2681c4f76a1c5c9383620b7b6.Client.Models
+@using sv_c95fa2b2681c4f76a1c5c9383620b7b6.Client.Services
+@inject IShipmentService ShipmentService
+@inject ILogger<ShipmentTracker> Logger
+@implements IDisposable
+
+<PageTitle>Shipment @TrackingNumber</PageTitle>
+
+@if (_loading)
+{
+    <div class="loading-placeholder">
+        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
+    </div>
+}
+else if (_errorMessage is not null)
+{
+    <div class="alert alert-danger">
+        <p>@_errorMessage</p>
+        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+else if (_shipment is null)
+{
+    <div class="alert alert-warning">
+        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
+    </div>
+}
+else
+{
+    <h3>Shipment @_shipment.TrackingNumber</h3>
+
+    <dl>
+        <dt>Status</dt>
+        <dd>@_shipment.Status</dd>
+
+        <dt>Current Location</dt>
+        <dd>@_shipment.Location</dd>
+
+        @if (_shipment.EstimatedDelivery.HasValue)
+        {
+            <dt>Estimated Delivery</dt>
+            <dd>@_shipment.EstimatedDelivery.Value.ToString("f")</dd>
+        }
+    </dl>
+
+    @if (_shipment.StatusUpdates.Count > 0)
+    {
+        <h4>Tracking History</h4>
+        <table class="table">
+            <thead>
+                <tr>
+                    <th>Time</th>
+                    <th>Status</th>
+                    <th>Location</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var update in _shipment.StatusUpdates)
+                {
+                    <tr>
+                        <td>@update.Timestamp.ToString("g")</td>
+                        <td>@update.Status</td>
+                        <td>@update.Location</td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    }
+}
+
+@code {
+    [Parameter]
+    public string TrackingNumber { get; set; } = string.Empty;
+
+    private Shipment? _shipment;
+    private bool _loading;
+    private string? _errorMessage;
+
+    private CancellationTokenSource? _cts;
+
+    protected override async Task OnParametersSetAsync()
+    {
+        await LoadShipmentAsync();
+    }
+
+    private async Task LoadShipmentAsync()
+    {
+        // Cancel any in-flight request before starting a new one.
+        CancelPendingRequest();
+
+        _loading = true;
+        _errorMessage = null;
+        _shipment = null;
+
+        var cts = new CancellationTokenSource();
+        _cts = cts;
+
+        try
+        {
+            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
+        }
+        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
+        {
+            // Request was intentionally cancelled (navigation change or dispose). Do nothing.
+            return;
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
+            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        await LoadShipmentAsync();
+    }
+
+    private void CancelPendingRequest()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+    }
+
+    public void Dispose()
+    {
+        CancelPendingRequest();
+    }
+}
